    public void CalculateBaseScore_InvalidOrIncompleteVectors_ReturnsNull(string? vector)
    {
        var score = CvssCalculator.CalculateBaseScore(vector);
        Assert.Null(score);
    }

    [Theory]
    [MemberData(nameof(OfficialFirstCvss404TestVectors))]
    public void CalculateBaseScore_OfficialFirstVectors_MatchesOracle(string vector, double expectedScore)
    {
        var score = CvssCalculator.CalculateBaseScore(vector);
        Assert.NotNull(score);
        Assert.Equal(expectedScore, score.Value);
    }

